with RecentSubscriptions as (select * from subscriptions where plan not in ('enterprise', 'basic', 'standard') and customer_id = 15), monthly_fee_bucket_summary as (select case when monthly_fee >= 203 then 'high' when monthly_fee >= 122 then 'mid' else 'low' end as monthly_fee_bucket, plan, concat_ws(', ', sort_array(collect_set(plan))) as plan_values from RecentSubscriptions group by case when monthly_fee >= 203 then 'high' when monthly_fee >= 122 then 'mid' else 'low' end, plan) select monthly_fee_bucket, plan_values from monthly_fee_bucket_summary order by 2, monthly_fee_bucket desc
